import{at as e,it as t,n,vt as r}from"./chunks/framework.BVWCHfG0.js";var i=JSON.parse(`{"title":"The\xA0less namespace","description":"","frontmatter":{},"headers":[],"relativePath":"syntaxes/less.md","filePath":"lib/syntaxes/less/README.md","lastUpdated":1790710395000}`),a={name:`syntaxes/less.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="the-less-namespace" tabindex="-1">The\xA0<code>less</code> namespace <a class="header-anchor" href="#the-less-namespace" aria-label="Permalink to “The\xA0less namespace”">​</a></h1><p>The\xA0rules of\xA0the\xA0core under\xA0<code>@stylistic/less/&lt;rule&gt;</code>, for\xA0stylesheets written in\xA0<a href="https://lesscss.org" target="_blank" rel="noreferrer">Less</a> and\xA0parsed with\xA0<a href="https://github.com/shellscape/postcss-less" target="_blank" rel="noreferrer"><code>postcss-less</code></a>. They are configured in\xA0the\xA0<code>overrides</code> block naming that\xA0syntax, as\xA0<a href="/user-guide/custom-syntaxes">Custom syntaxes</a> shows.</p><p>Every rule of\xA0the\xA0core is here, with\xA0the\xA0same options, <code>upper</code> of\xA0<code>at-rule-name-case</code> aside, and\xA0the\xA0same documentation, and\xA0plain CSS is read exactly as\xA0the\xA0core reads it\xA0— a\xA0plain block of\xA0an\xA0HTML page beside a\xA0<code>lang=&quot;less&quot;</code> one included, so\xA0a\xA0mixed page is configured with\xA0these rules alone, but\xA0for\xA0<code>upper</code> of\xA0<code>at-rule-name-case</code>, which\xA0its plain blocks take from\xA0the\xA0core&#39;s copy. What the\xA0namespace reads beyond the\xA0core:</p><ul><li>the\xA0constructs <code>postcss-less</code> hands over\xA0— mixins and\xA0their calls, variables (<code>@foo: bar;</code>), detached rulesets, <code>:extend</code>, CSS guards (<code>when</code>), maps\xA0— are passed over\xA0the\xA0way the\xA0core passes over\xA0what is not\xA0standard CSS, rather than\xA0misread as\xA0code;</li><li>an\xA0inline comment (<code>//</code>) is a\xA0comment of\xA0the\xA0text a\xA0rule reads, and\xA0every fix keeps out of\xA0one;</li><li><code>--fix</code> keeps the\xA0whitespace around a\xA0mixin call&#39;s <code>!important</code> on\xA0the\xA0side of\xA0the\xA0flag the\xA0file puts it, except that\xA0an\xA0end-of-line comment behind the\xA0flag still gets the\xA0flag moved behind it;</li><li><code>declaration-block-trailing-semicolon</code> under\xA0<code>never</code> reports and\xA0leaves the\xA0semicolons Less will not\xA0part with: behind an\xA0at-rule without\xA0a\xA0block (<code>a { @extend .b }</code> is an\xA0error to\xA0Less), a\xA0variable (<code>@v: pink</code>), and\xA0a\xA0declaration with\xA0no value (<code>color:;</code>), where a\xA0custom property&#39;s lone <code>!important</code> counts as\xA0a\xA0value; the\xA0semicolon behind a\xA0mixin call or\xA0a\xA0call to\xA0a\xA0detached ruleset, <code>@name()</code> and\xA0<code>@name()[key]</code> alike, goes as\xA0it does behind any declaration, while\xA0<code>@name ()</code> with\xA0a\xA0space is an\xA0at-rule;</li><li><code>at-rule-name-space-after</code> and\xA0<code>at-rule-name-newline-after</code> report an\xA0<code>@import</code> or\xA0<code>@plugin</code> with\xA0no whitespace behind the\xA0name, <code>@import(reference) &quot;x.less&quot;</code> or\xA0<code>@plugin&quot;p&quot;</code>, and\xA0write none into\xA0it, since\xA0Less takes the\xA0two\xA0as\xA0directives only with\xA0whitespace there;</li><li><code>at-rule-name-case</code> takes <code>lower</code> alone, since\xA0Less refuses an\xA0at-rule name holding an\xA0upper-case letter;</li><li><code>indentation</code> measures the\xA0head of\xA0a\xA0mixin definition as\xA0it measures an\xA0at-rule&#39;s parameters: a\xA0line continuing it outside the\xA0parameter list, a\xA0guard on\xA0a\xA0line of\xA0its own among them, stands a\xA0level deeper, and\xA0a\xA0line inside\xA0the\xA0list follows the\xA0parentheses as\xA0a\xA0mixin call&#39;s arguments do;</li><li><code>unit-case</code> reads and\xA0fixes the\xA0value of\xA0a\xA0variable (<code>@v: 10PX</code>) as\xA0it does a\xA0declaration&#39;s, whatever whitespace stands around the\xA0colon;</li><li><code>unit-case</code> reads a\xA0dimension as\xA0Less does: the\xA0number is digits with\xA0at\xA0most one period, and\xA0the\xA0unit ends at\xA0the\xA0first escape, hyphen or\xA0digit, so\xA0<code>10PX-2REM</code> has the\xA0units <code>PX</code> and\xA0<code>REM</code> and\xA0<code>1E5PX</code> the\xA0units <code>E</code> and\xA0<code>PX</code>, where the\xA0core reads the\xA0exponent into\xA0the\xA0number and\xA0the\xA0rest as\xA0one unit;</li><li>the\xA0<code>value-slash-space-*</code> and\xA0<code>media-feature-slash-space-*</code> rules read a\xA0solidus outside parentheses as\xA0the\xA0separator it is to\xA0the\xA0core, <code>2/@a</code> included, since\xA0Less divides only inside\xA0parentheses under\xA0its default <code>math</code> mode; a\xA0parenthesised group is passed over, and\xA0a\xA0variable&#39;s own value (<code>@a: 1/2</code>) is no declaration to\xA0them;</li><li><code>named-grid-areas-alignment</code> under\xA0<code>alignColumns</code> leaves a\xA0row without\xA0a\xA0line name at\xA0the\xA0indentation, since\xA0the\xA0empty list of\xA0names <code>[]</code> that\xA0would put it under\xA0the\xA0others is an\xA0error to\xA0Less.</li></ul><p>This namespace is about\xA0the\xA0stylistic side of\xA0the\xA0CSS a\xA0Less file holds. The\xA0Less constructs themselves\xA0— variables, mixins, guards\xA0— have no stylistic rules here.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};